alter table public.staff add column if not exists email text; create unique index if not exists staff_email_unique_idx on public.staff(lower(email)) where email is not null; update public.staff s set email=u.email from auth.users u where u.id=s.id and (s.email is null or lower(s.email)<>lower(u.email)); create or replace function private.sync_staff_email() returns trigger language plpgsql security definer set search_path = public, pg_temp as $$ begin update public.staff set email=new.email, updated_at=now() where id=new.id; return new; end; $$; drop trigger if exists sync_staff_email_after_auth_update on auth.users; create trigger sync_staff_email_after_auth_update after update of email on auth.users for each row execute function private.sync_staff_email();;
